public static int triangle(int rows) {
    if (rows <= 1) {
        return rows;
    }
    return rows + triangle(rows - 1);
}

public static int factorial(int n) {
    if (n <= 1) {
        return 1;
    }
    return n * factorial(n - 1);
}

public static int solve(int n) {
    if (n <= 1) {        // 1. the smallest input
        return 1;        //    and its answer
    }
    int smaller = solve(n - 1);   // 2. a smaller version (trust it!)
    return n + smaller;           // 3. finish the job
}
